python3 - <<'PY'
import subprocess, time, os, signal, json

tests = [
  ("context7", ["npx", "-y", "@upstash/context7-mcp", "--api-key", "ctx7sk-a7a9c423-8320-41bd-9904-8456936110ba"], {}),
  ("brave-search", ["npx", "-y", "@modelcontextprotocol/server-brave-search"], {"BRAVE_API_KEY": "BSA-_8ldghRCboWFMVQttdl0KTMqVEo"}),
  ("chrome-devtools", ["npx", "-y", "chrome-devtools-mcp@latest"], {}),
  ("netlify", ["npx", "-y", "@netlify/mcp"], {}),
]

for name, cmd, extra_env in tests:
    env = os.environ.copy()
    env.update(extra_env)
    print(f"=== {name} ===")
    try:
        p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, env=env)
        time.sleep(6)
        rc = p.poll()
        if rc is None:
            p.terminate()
            try:
                out, err = p.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                p.kill()
                out, err = p.communicate(timeout=5)
            print("STARTED: process stayed up long enough to suggest valid startup")
            if err.strip():
                print("stderr:", err.strip()[:700])
            elif out.strip():
                print("stdout:", out.strip()[:700])
        else:
            out, err = p.communicate(timeout=5)
            print(f"EXITED: rc={rc}")
            if err.strip():
                print("stderr:", err.strip()[:1000])
            if out.strip():
                print("stdout:", out.strip()[:1000])
    except Exception as e:
        print("ERROR:", repr(e))
